def _safe_json(resp: requests.Response) -> Dict[str, Any]:
    try:
        data = resp.json()
        if isinstance(data, dict):
            return data
        return {"data": data}
    except Exception:
        try:
            text = resp.text[:4000]
            return {"error": {"message": text}}
        except Exception:
            return {"error": {"message": ""}}


