@app.route("/api/health", methods=["GET"])
def health() -> Response:
    db_status: Dict[str, Any] = {"enabled": _db_enabled(), "available": _pg_available}
    pool = _get_db_pool() if _db_enabled() and _pg_available else None
    db_status["connected"] = pool is not None
    if pool is not None:
        try:
            conn = pool.getconn()
            try:
                conn.autocommit = True
                with conn.cursor() as cur:
                    cur.execute("SELECT 1")
                    row = cur.fetchone()
                    db_status["ok"] = bool(row and row[0] == 1)
            finally:
                pool.putconn(conn)
        except Exception as e:
            db_status["ok"] = False
            db_status["error"] = str(e)
    else:
        db_status["ok"] = False
    if _pg_import_error:
        db_status["import_error"] = _pg_import_error
    if _db_last_init_error:
        db_status["init_error"] = _db_last_init_error
    db_status["next_retry_epoch"] = _db_next_retry_ts if _db_next_retry_ts else None
    return jsonify({"ok": True, "db": db_status})


@app.route("/api/db/health", methods=["GET"])
def db_health() -> Response:
    if not _db_enabled():
        return jsonify({"ok": False, "enabled": False}), 503
    if not _pg_available:
        return jsonify({"ok": False, "enabled": True, "available": False, "import_error": _pg_import_error}), 500
    pool = _get_db_pool()
    if pool is None:
        return jsonify({"ok": False, "enabled": True, "available": True, "connected": False, "init_error": _db_last_init_error}), 503
    t0 = time.time()
    conn = pool.getconn()
    try:
        conn.autocommit = False
        with conn.cursor() as cur:
            cur.execute("SELECT NOW()")
            now_row = cur.fetchone()
            cur.execute(
                "INSERT INTO chat_logs (remote_addr, user_agent, model, request, reply, reasoning, tool_calls, web_search, parsed_files, error) "
                "VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s) RETURNING id",
                ("healthcheck", "healthcheck", "healthcheck", Json({"healthcheck": True}), None, None, None, Json([]), Json([]), None),
            )
            _ = cur.fetchone()
        conn.rollback()
        latency_ms = int((time.time() - t0) * 1000)
        return jsonify({"ok": True, "connected": True, "latency_ms": latency_ms, "now": str(now_row[0]) if now_row else None})
    except Exception as e:
        try:
            conn.rollback()
        except Exception:
            pass
        latency_ms = int((time.time() - t0) * 1000)
        return jsonify({"ok": False, "connected": True, "latency_ms": latency_ms, "error": str(e)}), 500
    finally:
        pool.putconn(conn)


def _handle_chat_common(stream: bool) -> Tuple[Dict[str, Any], List[Tuple[str, str]], List[Dict[str, Any]], Dict[str, Any], Dict[str, Any], bool]:
    req_json, parsed_files = _parse_request_payload()
    if not isinstance(req_json, dict):
        raise ValueError("JSON body must be an object")
    _coerce_thinking(req_json)
    messages = _normalize_messages(req_json.get("messages"))
    _validate_messages_limits(messages)
    max_total_file_chars = _env_int("MAX_FILE_TEXT_TOTAL_CHARS", 400000)
    total_file_chars = 0
    limited_files: List[Tuple[str, str]] = []
    for name, text in parsed_files:
        total_file_chars += len(text)
        if total_file_chars > max_total_file_chars:
            raise ValueError("parsed file text too large")
        limited_files.append((name, text))
    parsed_files = limited_files
    last_user_text = _latest_user_text(messages)
    trivial = _is_trivial_message(last_user_text)
    explicit_search_flag = ("search_enabled" in req_json) or ("web_search" in req_json) or ("search" in req_json)
    if explicit_search_flag:
        search_enabled = bool(req_json.get("search_enabled") or req_json.get("web_search") or req_json.get("search"))
    else:
        search_enabled = _should_auto_web_search(last_user_text, bool(parsed_files))
    search_results: List[Dict[str, Any]] = []
    search_meta: Dict[str, Any] = {"enabled": search_enabled}
    if search_enabled:
        max_user_msgs = req_json.get("search_context_user_messages")
        if max_user_msgs is None:
            max_user_msgs = _env_int("WEB_SEARCH_CONTEXT_USER_MESSAGES", 10)
        try:
            max_user_msgs_i = int(max_user_msgs)
        except Exception:
            max_user_msgs_i = 10
        max_user_msgs_i = max(1, min(max_user_msgs_i, 10))
        query_text = _extract_user_text_for_search(messages, _env_int("WEB_SEARCH_QUERY_INPUT_MAX_CHARS", 10000), max_user_msgs_i)
        opts = {
            "count": req_json.get("search_count"),
            "recency": req_json.get("search_recency_filter"),
            "engine": req_json.get("search_engine"),
            "content_size": req_json.get("search_content_size"),
            "search_intent": req_json.get("search_intent"),
            "query_max_chars": req_json.get("search_query_max_chars"),
        }
        search_results, search_meta = _web_search(query_text, opts)
    context_limits = {
        "max_total": req_json.get("max_context_chars"),
        "max_file_chars": req_json.get("max_file_text_chars"),
        "max_search_item_chars": req_json.get("max_search_item_chars"),
        "max_search_items": req_json.get("max_search_items"),
    }
    context_msg = _build_context_message(search_results, parsed_files, context_limits)
    body = _create_completion_body(req_json, messages, context_msg, stream=stream)
    body = _apply_speed_profile(body, trivial)
    return req_json, parsed_files, search_results, search_meta, body, trivial


def _sanitize_reply_for_response(reply: Any) -> Any:
    if reply is None or isinstance(reply, str):
        return reply
    try:
        return json.dumps(reply, ensure_ascii=False)
    except Exception:
        return str(reply)


