def _sse_line(obj: Union[str, Dict[str, Any]]) -> str:
    if obj == "[DONE]":
        return "data: [DONE]\n\n"
    return "data: " + json.dumps(obj, ensure_ascii=False) + "\n\n"


def _map_bigmodel_stream_obj_to_delta(obj: Dict[str, Any]) -> Tuple[Dict[str, Any], Optional[str]]:
    if obj.get("object") == "chat.completion.chunk" and "choices" in obj:
        try:
            ch = obj["choices"][0]
            delta = ch.get("delta") or {}
            fr = ch.get("finish_reason")
            if isinstance(delta, dict):
                if "reasoning_content" in ch:
                    delta["reasoning_content"] = ch.get("reasoning_content")
                return delta, fr
        except Exception:
            pass
    choices = obj.get("choices") or []
    if choices and isinstance(choices, list) and isinstance(choices[0], dict):
        first = choices[0]
        delta = first.get("delta") or {}
        fr = first.get("finish_reason")
        if isinstance(delta, dict):
            if "reasoning_content" in first:
                delta["reasoning_content"] = first.get("reasoning_content")
            return delta, fr
    if "delta" in obj and isinstance(obj["delta"], dict):
        return obj["delta"], obj.get("finish_reason")
    if "content" in obj:
        return {"content": obj.get("content")}, obj.get("finish_reason")
    return {}, obj.get("finish_reason")


@app.route("/api/chat/stream", methods=["POST", "OPTIONS"])
def chat_stream() -> Response:
    if request.method == "OPTIONS":
        return ("", 204)
    rl = _rate_limit_check()
    if rl is not None:
        return rl
    if not API_KEY:
        return _json_error("Missing BigModel API key in environment", 500)
    req_json: Dict[str, Any] = {}
    parsed_files: List[Tuple[str, str]] = []
    search_results: List[Dict[str, Any]] = []
    search_meta: Dict[str, Any] = {"enabled": False}
    trivial = False
    try:
        req_json, parsed_files, search_results, search_meta, body, trivial = _handle_chat_common(stream=True)
    except ValueError as e:
        try:
            parsed_meta = [{"name": n, "chars": len(t)} for n, t in parsed_files]
            _db_log_chat(DEFAULT_MODEL, req_json, None, None, None, search_results, parsed_meta, str(e), _client_ip(), request.headers.get("User-Agent"))
        except Exception:
            pass
        return _json_error(str(e), 400)
    except Exception as e:
        try:
            parsed_meta = [{"name": n, "chars": len(t)} for n, t in parsed_files]
            _db_log_chat(DEFAULT_MODEL, req_json, None, None, None, search_results, parsed_meta, str(e), _client_ip(), request.headers.get("User-Agent"))
        except Exception:
            pass
        log.exception("Stream request failed")
        return _json_error("Stream request failed", 500, str(e))

    chunk_id = "chatcmpl-" + uuid.uuid4().hex
    model = body["model"]
    remote_addr = _client_ip()
    user_agent = request.headers.get("User-Agent")
    parsed_meta = [{"name": n, "chars": len(t)} for n, t in parsed_files]
    max_acc = _env_int("STREAM_ACC_MAX_CHARS", 1000000)
    max_reason = _env_int("STREAM_REASON_MAX_CHARS", 500000)
    max_tool_arg_chars = _env_int("STREAM_MAX_TOOL_ARG_CHARS", 200000)

    def gen() -> Iterable[str]:
        acc_parts: List[str] = []
        reason_parts: List[str] = []
        acc_len = 0
        reason_len = 0
        tool_calls: Dict[int, Dict[str, Any]] = defaultdict(dict)
        err: Optional[str] = None
        final_fr: Optional[str] = None
        try:
            yield _sse_line({"type": "start", "id": chunk_id, "model": model, "web_search_enabled": bool(search_meta.get("enabled"))})
            timeout = _env_float("CHAT_STREAM_TIMEOUT_TRIVIAL", 45.0) if trivial else _env_float("CHAT_STREAM_TIMEOUT", 900.0)
            raw_lines = _bigmodel_stream_raw("/chat/completions", body, timeout=timeout)
            for item in _parse_sse_data_lines(raw_lines):
                if item == "[DONE]":
                    break
                if not isinstance(item, dict):
                    continue
                delta, finish_reason = _map_bigmodel_stream_obj_to_delta(item)
                if not isinstance(delta, dict):
                    delta = {}
                out: Dict[str, Any] = {}
                if "content" in delta and delta["content"] is not None:
                    s = str(delta["content"])
                    out["content"] = s
                    if max_acc <= 0 or acc_len + len(s) <= max_acc:
                        acc_parts.append(s)
                        acc_len += len(s)
                if "reasoning_content" in delta and delta["reasoning_content"] is not None:
                    rs = str(delta["reasoning_content"])
                    out["reasoning_content"] = rs
                    if max_reason <= 0 or reason_len + len(rs) <= max_reason:
                        reason_parts.append(rs)
                        reason_len += len(rs)
                if "tool_calls" in delta and delta["tool_calls"] is not None:
                    out["tool_calls"] = delta["tool_calls"]
                    for tc_delta in delta["tool_calls"]:
                        idx = tc_delta.get("index", 0)
                        if idx not in tool_calls:
                            tool_calls[idx] = {
                                "id": tc_delta.get("id"),
                                "type": tc_delta.get("type", "function"),
                                "function": {
                                    "name": tc_delta.get("function", {}).get("name", ""),
                                    "arguments": "",
                                },
                            }
                        else:
                            if tc_delta.get("id") and not tool_calls[idx].get("id"):
                                tool_calls[idx]["id"] = tc_delta["id"]
                            if tc_delta.get("type") and not tool_calls[idx].get("type"):
                                tool_calls[idx]["type"] = tc_delta["type"]
                            fn = tc_delta.get("function", {})
                            if fn.get("name") and not tool_calls[idx]["function"].get("name"):
                                tool_calls[idx]["function"]["name"] = fn["name"]
                        fn_delta = tc_delta.get("function", {})
                        if isinstance(fn_delta, dict) and "arguments" in fn_delta:
                            arg_chunk = fn_delta["arguments"]
                            current_args = tool_calls[idx]["function"]["arguments"]
                            if max_tool_arg_chars <= 0 or len(current_args) + len(arg_chunk) <= max_tool_arg_chars:
                                tool_calls[idx]["function"]["arguments"] += arg_chunk
                if out:
                    payload_out: Dict[str, Any] = {"type": "delta"}
                    if "content" in out:
                        payload_out["content"] = out["content"]
                    if "reasoning_content" in out:
                        payload_out["reasoning"] = out["reasoning_content"]
                    if "tool_calls" in out:
                        payload_out["tool_calls"] = out["tool_calls"]
                    yield _sse_line(payload_out)
                if finish_reason is not None:
                    final_fr = str(finish_reason)
                    break
            if final_fr is None:
                final_fr = "stop"
            reply_full = "".join(acc_parts)
            reason_full = "".join(reason_parts)
            tool_calls_val: Any = [tool_calls[i] for i in sorted(tool_calls)] if tool_calls else None
            yield _sse_line({"type": "final", "reply": reply_full, "reasoning": reason_full, "tool_calls": tool_calls_val, "finish_reason": final_fr})
            yield _sse_line("[DONE]")
        except GeneratorExit:
            err = "client disconnected"
            raise
        except Exception as e:
            err = str(e)
            log.exception("Stream generation error")
            try:
                yield _sse_line({"type": "error", "message": err})
                yield _sse_line("[DONE]")
            except Exception:
                pass
        finally:
            try:
                reply_full2 = "".join(acc_parts)
                reason_full2 = "".join(reason_parts)
                tool_calls_val2: Any = [tool_calls[i] for i in sorted(tool_calls)] if tool_calls else None
                _db_log_chat(model, req_json, reply_full2, reason_full2, tool_calls_val2, search_results, parsed_meta, err, remote_addr, user_agent)
            except Exception:
                pass

    return Response(stream_with_context(gen()), mimetype="text/event-stream")


def _serve_file(path: str) -> Optional[Response]:
    root = os.path.abspath(os.getcwd())
    target = os.path.abspath(os.path.join(root, path))
    if not target.startswith(root + os.sep):
        return None
    if os.path.isfile(target):
        rel_dir = os.path.dirname(os.path.relpath(target, root))
        fname = os.path.basename(target)
        return send_from_directory(os.path.join(root, rel_dir) if rel_dir else root, fname)
    return None


@app.route("/", defaults={"path": ""})
@app.route("/<path:path>")
def index(path: str) -> Response:
    if path.startswith("api/") or path == "api":
        abort(404)
    if path:
        file_resp = _serve_file(path)
        if file_resp is not None:
            return file_resp
    if os.path.isfile("index.html"):
        return send_from_directory(os.getcwd(), "index.html")
    abort(404)


